## Security Testing Principles

### Test What Should Work (Positive Tests)
- Valid inputs are accepted
- Legitimate users can access resources
- Proper functionality works as expected

### Test What Should Fail (Negative Tests)
- Malicious inputs are rejected
- Unauthorized access is denied
- Attack attempts are blocked
- Errors don't leak sensitive information

---

## Security Test Patterns

### 1. SQL Injection Tests

```typescript
import { describe, it, expect } from 'test-framework';
import { getUserById } from './user-service';

describe('SQL Injection Prevention', () => {
  describe('Positive tests', () => {
    it('should retrieve user with valid ID', async () => {
      const user = await getUserById('123');
      expect(user).toBeDefined();
      expect(user.id).toBe('123');
    });
  });

  describe('Negative tests - SQL injection attempts', () => {
    it('should reject SQL injection in ID parameter', async () => {
      const maliciousInputs = [
        "1' OR '1'='1",
        "1; DROP TABLE users--",
        "1' UNION SELECT * FROM passwords--"
      ];

      for (const input of maliciousInputs) {
        await expect(getUserById(input))
          .rejects.toThrow(/Invalid|Validation/);
      }
    });

    it('should sanitize special characters', async () => {
      const result = await getUserById("1'; --");
      // Should either reject or safely handle
      expect(result).toBeNull(); // Or throw error
    });
  });
});
```

### 2. XSS Prevention Tests

```typescript
import { render, screen } from '@testing-library/react';
import { CommentDisplay } from './CommentDisplay';

describe('XSS Prevention', () => {
  describe('Positive tests', () => {
    it('should display normal comment text', () => {
      render(<CommentDisplay comment="Hello world" />);
      expect(screen.getByText('Hello world')).toBeInTheDocument();
    });
  });

  describe('Negative tests - XSS attempts', () => {
    it('should escape script tags in user input', () => {
      const xssPayload = '<script>alert("XSS")</script>';
      const { container } = render(<CommentDisplay comment={xssPayload} />);

      // Script should be escaped, not executed
      expect(container.querySelector('script')).toBeNull();
      expect(container.textContent).toContain('<script>');
    });

    it('should sanitize event handlers', () => {
      const payload = '<img src=x onerror="alert(1)" />';
      const { container } = render(<CommentDisplay comment={payload} />);

      const img = container.querySelector('img');
      if (img) {
        expect(img.getAttribute('onerror')).toBeNull();
      }
    });

    it('should handle JavaScript URL schemes', () => {
      const payload = '<a href="javascript:alert(1)">Click</a>';
      const { container } = render(<CommentDisplay comment={payload} />);

      const link = container.querySelector('a');
      if (link) {
        expect(link.getAttribute('href')).not.toContain('javascript:');
      }
    });
  });
});
```

### 3. Authentication Tests

```typescript
import { authenticateUser, generateToken } from './auth';

describe('Authentication Security', () => {
  describe('Positive tests', () => {
    it('should authenticate with valid credentials', async () => {
      const result = await authenticateUser('user@example.com', 'ValidPass123!');
      expect(result.token).toBeDefined();
      expect(result.user).toBeDefined();
    });
  });

  describe('Negative tests - Authentication bypass attempts', () => {
    it('should reject authentication without password', async () => {
      await expect(authenticateUser('user@example.com', ''))
        .rejects.toThrow(/Invalid credentials/);
    });

    it('should reject SQL injection in username', async () => {
      await expect(authenticateUser("admin' OR '1'='1", 'anypass'))
        .rejects.toThrow();
    });

    it('should not reveal if user exists', async () => {
      const error1 = await authenticateUser('exists@example.com', 'wrong')
        .catch(e => e.message);
      const error2 = await authenticateUser('noexist@example.com', 'wrong')
        .catch(e => e.message);

      // Both should have same error message (timing-safe)
      expect(error1).toBe(error2);
    });

    it('should reject weak passwords', async () => {
      await expect(registerUser('user@example.com', '12345'))
        .rejects.toThrow(/Password too weak/);
    });
  });

  describe('Token security', () => {
    it('should reject expired tokens', async () => {
      const expiredToken = generateToken({ userId: '123' }, { expiresIn: '-1h' });
      await expect(verifyToken(expiredToken))
        .rejects.toThrow(/expired/);
    });

    it('should reject tampered tokens', async () => {
      const validToken = generateToken({ userId: '123' });
      const tamperedToken = validToken.slice(0, -5) + 'XXXXX';

      await expect(verifyToken(tamperedToken))
        .rejects.toThrow(/invalid/);
    });
  });
});
```

### 4. Authorization Tests

```typescript
import { deleteUser } from './user-service';
import { createMockRequest } from './test-utils';

describe('Authorization Security', () => {
  describe('Positive tests', () => {
    it('should allow admin to delete any user', async () => {
      const adminReq = createMockRequest({ userId: 'admin1', role: 'admin' });
      await expect(deleteUser(adminReq, 'user123')).resolves.toBeDefined();
    });

    it('should allow user to delete their own account', async () => {
      const userReq = createMockRequest({ userId: 'user123', role: 'user' });
      await expect(deleteUser(userReq, 'user123')).resolves.toBeDefined();
    });
  });

  describe('Negative tests - Privilege escalation attempts', () => {
    it('should prevent regular user from deleting other users', async () => {
      const userReq = createMockRequest({ userId: 'user123', role: 'user' });
      await expect(deleteUser(userReq, 'user456'))
        .rejects.toThrow(/Forbidden|Not authorized/);
    });

    it('should prevent unauthenticated access', async () => {
      const anonReq = createMockRequest(null);
      await expect(deleteUser(anonReq, 'user123'))
        .rejects.toThrow(/Unauthorized/);
    });

    it('should validate role in token', async () => {
      // Token says admin, but DB says user
      const fakeAdminReq = createMockRequest({ userId: 'user123', role: 'admin' });

      // Should verify role against database, not just trust token
      await expect(deleteUser(fakeAdminReq, 'user456'))
        .rejects.toThrow();
    });
  });
});
```

### 5. Input Validation Tests

```typescript
import { validateUserInput } from './validation';

describe('Input Validation Security', () => {
  describe('Positive tests', () => {
    it('should accept valid input', () => {
      const valid = { email: 'user@example.com', age: 25, username: 'john_doe' };
      expect(() => validateUserInput(valid)).not.toThrow();
    });
  });

  describe('Negative tests - Malicious input', () => {
    it('should reject input with null bytes', () => {
      const malicious = { username: 'admin\x00' };
      expect(() => validateUserInput(malicious)).toThrow(/Invalid/);
    });

    it('should reject excessively long input', () => {
      const malicious = { username: 'a'.repeat(10000) };
      expect(() => validateUserInput(malicious)).toThrow(/too long/);
    });

    it('should reject invalid email formats', () => {
      const inputs = [
        { email: 'not-an-email' },
        { email: '@example.com' },
        { email: 'user@' },
        { email: '<script>@example.com' }
      ];

      inputs.forEach(input => {
        expect(() => validateUserInput(input)).toThrow();
      });
    });

    it('should reject path traversal attempts', () => {
      const malicious = { filename: '../../../etc/passwd' };
      expect(() => validateFileInput(malicious)).toThrow(/Invalid path/);
    });
  });
});
```

### 6. Error Handling Security Tests

```typescript
import { request } from 'supertest';
import { app } from './app';

describe('Error Handling Security', () => {
  it('should not leak stack traces', async () => {
    const response = await request(app)
      .get('/api/error-trigger')
      .expect(500);

    expect(response.body.error).toBeDefined();
    expect(response.body.error).not.toContain('at Object.');
    expect(response.body.error).not.toContain('.js:');
    expect(response.body.stack).toBeUndefined();
  });

  it('should not reveal internal paths', async () => {
    const response = await request(app)
      .get('/api/nonexistent')
      .expect(404);

    expect(response.body.error).not.toContain('/home/');
    expect(response.body.error).not.toContain('/usr/');
    expect(response.body.error).not.toContain('node_modules');
  });

  it('should not expose database errors', async () => {
    const response = await request(app)
      .post('/api/users')
      .send({ email: 'invalid' })
      .expect(400);

    expect(response.body.error).not.toContain('SQL');
    expect(response.body.error).not.toContain('database');
    expect(response.body.error).not.toContain('query');
  });
});
```

